	var unreadable []unreadableFactBranchStore
	for _, branch := range source.Branches {
		if branch == "" {
			continue
		}
		if _, err := loadFacts(brainDir, branch); err != nil {
			unreadable = append(unreadable, unreadableFactBranchStore{Branch: branch, Err: err})
		}
	}
